values
  ('beds', 'Number of bedrooms', 'unit', 'rent', 'floor_plan', '{"type": "integer", "minimum": 0, "maximum": 5}'::jsonb, null, '[{"match": {"op": "eq", "value": 2}, "delta": 0.5}, {"match": {"op": "eq", "value": 1}, "delta": 0.0}, {"match": {"op": "eq", "value": 0}, "delta": -0.5}]'::jsonb, 'Count distinct bedrooms; a studio is 0.', null, 'listing_details', 'decision_relevant', 'standard_ladder'),
  ('baths', 'Number of bathrooms', 'unit', 'rent', 'floor_plan', '{"type": "number", "minimum": 1, "maximum": 4, "multipleOf": 0.5}'::jsonb, null, '[{"match": {"op": "gt", "value": 1.5}, "delta": 0.5}, {"match": {"op": "eq", "value": 1.5}, "delta": 0.25}, {"match": {"op": "eq", "value": 1}, "delta": 0.0}]'::jsonb, 'Count bathrooms; a half bath (no shower/tub) counts 0.5.', null, 'listing_details', 'decision_relevant', 'standard_ladder'),
  ('sqft', 'Square footage', 'unit', 'rent', 'floor_plan', '{"type": "integer", "minimum": 0}'::jsonb, null, '[{"match": {"op": "gt", "value": 1000}, "delta": 0.5}, {"match": {"op": "range", "value": [700, 1000]}, "delta": 0.0}, {"match": {"op": "lt", "value": 700}, "delta": -0.5}]'::jsonb, 'Interior area of the unit in square feet.', null, 'listing_details', 'decision_relevant', 'standard_ladder'),
  ('patio_balcony', 'Patio or balcony', 'unit', 'rent', 'floor_plan', '{"type": "string", "enum": ["confirmed", "advertised_unconfirmed", "none"]}'::jsonb, '{"type": "boolean"}'::jsonb, '[{"match": {"op": "eq", "value": "confirmed"}, "delta": 0.5}, {"match": {"op": "eq", "value": "advertised_unconfirmed"}, "delta": 0.0}, {"match": {"op": "eq", "value": "none"}, "delta": 0.0}]'::jsonb, 'True if the unit has a private patio or balcony.', null, 'listing_details', 'decision_relevant', 'standard_ladder'),
  ('private_entry', 'Private entrance', 'unit', 'rent', 'floor_plan', '{"type": "string", "enum": ["confirmed", "advertised_unconfirmed", "none"]}'::jsonb, '{"type": "boolean"}'::jsonb, '[{"match": {"op": "eq", "value": "confirmed"}, "delta": 0.25}, {"match": {"op": "eq", "value": "advertised_unconfirmed"}, "delta": 0.0}, {"match": {"op": "eq", "value": "none"}, "delta": 0.0}]'::jsonb, 'True if the unit has its own exterior entrance rather than a shared interior corridor.', null, 'listing_details', 'decision_relevant', 'standard_ladder'),
  ('in_unit_laundry', 'Laundry', 'fittings', 'rent', 'mixed', '{"type": "array", "items": {"type": "string", "enum": ["in_unit", "hookups", "on_site", "none", "advertised_unconfirmed"]}, "minItems": 1, "uniqueItems": true}'::jsonb, '{"type": "string", "enum": ["in_unit", "hookups", "on_site", "none"]}'::jsonb, '[{"match": {"op": "contains_any", "value": ["in_unit"]}, "delta": 0.0}, {"match": {"op": "contains_any", "value": ["hookups"]}, "delta": -0.25}, {"match": {"op": "contains_any", "value": ["on_site"]}, "delta": -1.0}, {"match": {"op": "contains_any", "value": ["none"]}, "delta": -2.0}, {"match": {"op": "contains_any", "value": ["advertised_unconfirmed"]}, "delta": 0.0}]'::jsonb, 'in_unit = washer/dryer inside the unit; hookups = connections only; on_site = shared laundry room/facilities; none = the page explicitly states that no laundry option of any kind is available. A statement that in-unit laundry is unavailable is not `none` when hookups or shared facilities are stated. Emit one claim per distinct supported mode; distinct positive modes may coexist at one concrete target.', null, 'listing_details', 'decision_relevant', 'standard_ladder'),
  ('pets_policy', 'Pets policy', 'tenancy', 'rent', 'property', '{"type": "string", "enum": ["cats_and_dogs", "cats_only", "dogs_only", "none"]}'::jsonb, null, '[{"match": {"op": "eq", "value": "cats_and_dogs"}, "delta": 0.0}, {"match": {"op": "eq", "value": "cats_only"}, "delta": 0.0}, {"match": {"op": "eq", "value": "dogs_only"}, "delta": -1.0}, {"match": {"op": "eq", "value": "none"}, "delta": -1.0}]'::jsonb, 'Which pets the policy allows, ignoring breed and weight limits.If a fee is mentioned for a pet, then we can consider it a pet policy criterion.', null, 'listing_details', 'decision_relevant', 'standard_ladder'),
  ('all_in_monthly', 'All-in monthly cost', 'cost', 'rent', 'composed', '{"type": "number", "minimum": 0}'::jsonb, null, '[{"match": {"op": "lt", "value": 1500}, "delta": 1.0}, {"match": {"op": "range", "value": [1500, 1800]}, "delta": 0.5}, {"match": {"op": "range", "value": [1800, 2000]}, "delta": 0.25}, {"match": {"op": "range", "value": [2000, 2100]}, "delta": 0.0}, {"match": {"op": "range", "value": [2100, 2200]}, "delta": -0.5}, {"match": {"op": "range", "value": [2200, 2400]}, "delta": -1.0}, {"match": {"op": "gt", "value": 2400}, "delta": -2.0}]'::jsonb, 'Composed by the pipeline from rent, mandatory fees, pet costs, and utility estimates (DESIGN §9.5) — never extracted directly from the page.', null, 'pricing', 'decision_relevant', 'standard_ladder'),
  ('security_deposit', 'Security deposit', 'cost', 'rent', 'floor_plan', '{"type": "number", "minimum": 0}'::jsonb, null, '[{"match": {"op": "lt", "value": 500}, "delta": 0.25}, {"match": {"op": "range", "value": [500, 1000]}, "delta": 0.0}, {"match": {"op": "gt", "value": 1000}, "delta": -0.25}]'::jsonb, 'Refundable security deposit in dollars; use the standard amount, not a promotional one.', null, 'pricing', 'decision_relevant', 'standard_ladder'),
  ('estimated_move_in_cost', 'Estimated move-in cost', 'cost', 'rent', 'composed', '{"type": "number", "minimum": 0}'::jsonb, null, '[{"match": {"op": "lt", "value": 2500}, "delta": 1.0}, {"match": {"op": "range", "value": [2500, 4000]}, "delta": 0.5}, {"match": {"op": "range", "value": [4000, 5500]}, "delta": 0.0}, {"match": {"op": "range", "value": [5500, 7000]}, "delta": -0.5}, {"match": {"op": "gt", "value": 7000}, "delta": -1.0}]'::jsonb, 'Composed by the pipeline (P3-SC8, DESIGN §9.5) from the first month''s all-in, the security deposit, required one-time fees and prepaids — never extracted directly from the page. A missing required component leaves it unknown.', null, 'pricing', 'decision_relevant', 'standard_ladder'),
  ('availability_date', 'Availability date', 'tenancy', 'rent', 'floor_plan', '{"type": "string", "format": "date"}'::jsonb, null, '[]'::jsonb, 'Earliest stated move-in date for the unit, as an ISO date (YYYY-MM-DD). Search prose and [EMBEDDED DATA]. If the target Property/Floor Plan has an explicit availability date, emit the earliest explicit ISO date even when the UI also says ''Available Now'', ''Now'', or ''Immediately''. Emit the literal sentinel available_now only when that target has immediate wording and no explicit availability date — never invent a calendar date. Ignore similar/nearby Properties, page update timestamps, promotions, and unrelated dates. Property-level availability is the earliest relevant date across the target Property''s plans. The pipeline rewrites available_now to the run date (live) or corpus saved_at date (bench).', null, 'pricing', 'decision_relevant', 'standard_ladder'),
  ('kitchen_quality', 'Kitchen quality', 'fittings', 'rent', 'floor_plan', '{"type": "integer", "minimum": 1, "maximum": 5}'::jsonb, null, '[{"match": {"op": "gt", "value": 3}, "delta": 0.5}, {"match": {"op": "eq", "value": 3}, "delta": 0.0}, {"match": {"op": "lt", "value": 3}, "delta": -0.5}]'::jsonb, '1-5 rating assessed by VISION from listing photos against the anchored reference set (DESIGN §10.8), not from text.', 'vision', 'images', 'decision_relevant', 'standard_ladder'),
  ('flooring_quality', 'Flooring quality', 'fittings', 'rent', 'floor_plan', '{"type": "integer", "minimum": 1, "maximum": 5}'::jsonb, null, '[{"match": {"op": "gt", "value": 3}, "delta": 0.5}, {"match": {"op": "eq", "value": 3}, "delta": 0.0}, {"match": {"op": "lt", "value": 3}, "delta": -0.5}]'::jsonb, '1-5 rating of floor/carpet condition assessed by VISION from listing photos against the anchored reference set, not from text.', 'vision', 'images', 'decision_relevant', 'standard_ladder'),
  ('flooring_materials', 'Flooring materials', 'fittings', 'rent', 'mixed', '{"type": "array", "items": {"type": "string", "enum": ["carpet", "hardwood", "engineered_wood", "laminate", "vinyl", "tile", "concrete", "other"]}, "minItems": 1, "uniqueItems": true}'::jsonb, null, '[{"match": {"op": "contains_any", "value": ["carpet", "hardwood", "engineered_wood", "laminate", "vinyl", "tile", "concrete", "other"]}, "delta": 0.0}]'::jsonb, 'Objective flooring materials inside the unit. Use only carpet, hardwood, engineered_wood, laminate, vinyl, tile, concrete, or other; include every explicitly stated material for the concrete target. Do not infer material from appearance or use this field for condition/quality.', null, 'listing_details', 'decision_relevant', 'standard_ladder'),
  ('parking', 'Parking', 'unit', 'rent', 'mixed', '{"type": "array", "items": {"type": "string", "enum": ["garage", "carport", "covered", "dedicated_lot", "street_only", "none", "advertised_unconfirmed"]}, "minItems": 1, "uniqueItems": true}'::jsonb, '{"type": "string", "enum": ["garage", "carport", "covered", "dedicated_lot", "street_only", "none"]}'::jsonb, '[{"match": {"op": "contains_any", "value": ["garage"]}, "delta": 0.5}, {"match": {"op": "contains_any", "value": ["carport"]}, "delta": 0.25}, {"match": {"op": "contains_any", "value": ["covered"]}, "delta": 0.25}, {"match": {"op": "contains_any", "value": ["dedicated_lot"]}, "delta": 0.0}, {"match": {"op": "contains_any", "value": ["street_only"]}, "delta": -0.5}, {"match": {"op": "contains_any", "value": ["none"]}, "delta": -1.0}, {"match": {"op": "contains_any", "value": ["advertised_unconfirmed"]}, "delta": 0.0}]'::jsonb, 'Parking included or available with the unit: garage, carport, covered, dedicated_lot (assigned or off-street lot), street_only, or none. Emit one claim per distinct supported type; positive types may coexist.', null, 'listing_details', 'decision_relevant', 'standard_ladder'),
  ('cooling', 'Cooling', 'fittings', 'rent', 'floor_plan', '{"type": "array", "items": {"type": "string", "enum": ["central", "window_units", "none", "advertised_unconfirmed"]}, "minItems": 1, "uniqueItems": true}'::jsonb, '{"type": "string", "enum": ["central", "window_units", "none"]}'::jsonb, '[{"match": {"op": "contains_any", "value": ["central"]}, "delta": 0.5}, {"match": {"op": "contains_any", "value": ["window_units"]}, "delta": 0.0}, {"match": {"op": "contains_any", "value": ["none"]}, "delta": -1.0}, {"match": {"op": "contains_any", "value": ["advertised_unconfirmed"]}, "delta": 0.0}]'::jsonb, 'central = central air conditioning; window_units = window/wall units provided or explicitly permitted; none otherwise.', null, 'listing_details', 'decision_relevant', 'standard_ladder'),
  ('dishwasher', 'Dishwasher', 'fittings', 'rent', 'floor_plan', '{"type": "string", "enum": ["confirmed", "advertised_unconfirmed", "none"]}'::jsonb, '{"type": "boolean"}'::jsonb, '[{"match": {"op": "eq", "value": "confirmed"}, "delta": 0.25}, {"match": {"op": "eq", "value": "advertised_unconfirmed"}, "delta": 0.0}, {"match": {"op": "eq", "value": "none"}, "delta": 0.0}]'::jsonb, 'True if the unit includes a dishwasher.', null, 'listing_details', 'decision_relevant', 'standard_ladder'),
  ('walk_in_closets', 'Walk-in closets', 'fittings', 'rent', 'floor_plan', '{"type": "string", "enum": ["confirmed", "advertised_unconfirmed", "none"]}'::jsonb, '{"type": "boolean"}'::jsonb, '[{"match": {"op": "eq", "value": "confirmed"}, "delta": 0.25}, {"match": {"op": "eq", "value": "advertised_unconfirmed"}, "delta": 0.0}, {"match": {"op": "eq", "value": "none"}, "delta": 0.0}]'::jsonb, 'True only for an explicitly stated walk-in closet inside the unit; large or ample closets alone are not sufficient.', null, 'listing_details', 'available_sources_only', 'verified_positive_preferred'),
  ('pantry', 'Pantry', 'fittings', 'rent', 'floor_plan', '{"type": "string", "enum": ["confirmed", "advertised_unconfirmed", "none"]}'::jsonb, '{"type": "boolean"}'::jsonb, '[{"match": {"op": "eq", "value": "confirmed"}, "delta": 0.25}, {"match": {"op": "eq", "value": "advertised_unconfirmed"}, "delta": 0.0}, {"match": {"op": "eq", "value": "none"}, "delta": 0.0}]'::jsonb, 'True only when the unit explicitly includes a pantry; cabinet or walk-in pantry details may remain in the evidence.', null, 'listing_details', 'available_sources_only', 'verified_positive_preferred'),
  ('disposal', 'Garbage disposal', 'fittings', 'rent', 'floor_plan', '{"type": "string", "enum": ["confirmed", "advertised_unconfirmed", "none"]}'::jsonb, '{"type": "boolean"}'::jsonb, '[{"match": {"op": "eq", "value": "confirmed"}, "delta": 0.25}, {"match": {"op": "eq", "value": "advertised_unconfirmed"}, "delta": 0.0}, {"match": {"op": "eq", "value": "none"}, "delta": 0.0}]'::jsonb, 'True only when the unit explicitly includes a kitchen garbage disposal.', null, 'listing_details', 'available_sources_only', 'verified_positive_preferred'),
  ('fireplace', 'Fireplace', 'fittings', 'rent', 'floor_plan', '{"type": "string", "enum": ["confirmed", "advertised_unconfirmed", "none"]}'::jsonb, '{"type": "boolean"}'::jsonb, '[{"match": {"op": "eq", "value": "confirmed"}, "delta": 0.25}, {"match": {"op": "eq", "value": "advertised_unconfirmed"}, "delta": 0.0}, {"match": {"op": "eq", "value": "none"}, "delta": 0.0}]'::jsonb, 'True only for a fireplace inside the unit, not a clubhouse, lounge, outdoor fireplace, or fire pit.', null, 'listing_details', 'available_sources_only', 'verified_positive_preferred'),
  ('ceiling_fans', 'Ceiling fans', 'fittings', 'rent', 'floor_plan', '{"type": "string", "enum": ["confirmed", "advertised_unconfirmed", "none"]}'::jsonb, '{"type": "boolean"}'::jsonb, '[{"match": {"op": "eq", "value": "confirmed"}, "delta": 0.25}, {"match": {"op": "eq", "value": "advertised_unconfirmed"}, "delta": 0.0}, {"match": {"op": "eq", "value": "none"}, "delta": 0.0}]'::jsonb, 'True only when the unit explicitly includes one or more ceiling fans.', null, 'listing_details', 'available_sources_only', 'verified_positive_preferred'),
  ('stainless_steel_appliances', 'Stainless steel appliances', 'fittings', 'rent', 'floor_plan', '{"type": "string", "enum": ["confirmed", "advertised_unconfirmed", "none"]}'::jsonb, '{"type": "boolean"}'::jsonb, '[{"match": {"op": "eq", "value": "confirmed"}, "delta": 0.25}, {"match": {"op": "eq", "value": "advertised_unconfirmed"}, "delta": 0.0}, {"match": {"op": "eq", "value": "none"}, "delta": 0.0}]'::jsonb, 'True only when the unit''s appliance finish is explicitly stainless steel; this does not assert appliance age, condition, or quality.', null, 'listing_details', 'available_sources_only', 'verified_positive_preferred'),
  ('min_lease_months', 'Minimum lease term', 'tenancy', 'rent', 'mixed', '{"type": "integer", "minimum": 1}'::jsonb, null, '[{"match": {"op": "lt", "value": 12}, "delta": 0.25}, {"match": {"op": "eq", "value": 12}, "delta": 0.0}, {"match": {"op": "gt", "value": 12}, "delta": -0.5}]'::jsonb, 'Shortest lease term offered, in months; month-to-month is 1.', null, 'pricing', 'decision_relevant', 'standard_ladder'),
  ('grocery_proximity', 'Grocery proximity', 'location', 'rent', 'property', '{"type": "number", "minimum": 0}'::jsonb, null, '[{"match": {"op": "lt", "value": 10}, "delta": 0.5}, {"match": {"op": "range", "value": [10, 20]}, "delta": 0.0}, {"match": {"op": "gt", "value": 20}, "delta": -0.5}]'::jsonb, 'Minutes to the nearest full grocery store, walking or driving per the hunt setting; computed via Maps, not extracted from the page.', 'maps', 'location', 'decision_relevant', 'standard_ladder'),
  ('management_reviews', 'Management reviews', 'management', 'rent', 'property', '{"type": "object", "properties": {"rating": {"type": "number", "minimum": 1, "maximum": 5}, "summary": {"type": "string"}}, "required": ["rating"]}'::jsonb, null, '[{"match": {"op": "gt", "value": 4}, "delta": 0.5}, {"match": {"op": "range", "value": [3, 4]}, "delta": 0.0}, {"match": {"op": "lt", "value": 3}, "delta": -0.5}]'::jsonb, 'Aggregate review rating (1-5) plus a short reputation summary, sourced from Places reviews.', 'maps', 'reviews', 'decision_relevant', 'standard_ladder'),
  ('location_safety', 'Location safety', 'location', 'rent', 'property', '{"type": "string", "enum": ["A+", "A", "A-", "B+", "B", "B-", "C+", "C", "C-", "D+", "D", "D-", "F"]}'::jsonb, null, '[{"match": {"op": "eq", "value": "A+"}, "delta": 0.5}, {"match": {"op": "eq", "value": "A"}, "delta": 0.5}, {"match": {"op": "eq", "value": "A-"}, "delta": 0.5}, {"match": {"op": "eq", "value": "B+"}, "delta": 0.25}, {"match": {"op": "eq", "value": "B"}, "delta": 0.25}, {"match": {"op": "eq", "value": "B-"}, "delta": 0.25}, {"match": {"op": "eq", "value": "C+"}, "delta": 0.0}, {"match": {"op": "eq", "value": "C"}, "delta": 0.0}, {"match": {"op": "eq", "value": "C-"}, "delta": 0.0}, {"match": {"op": "eq", "value": "D+"}, "delta": -0.5}, {"match": {"op": "eq", "value": "D"}, "delta": -0.5}, {"match": {"op": "eq", "value": "D-"}, "delta": -0.5}, {"match": {"op": "eq", "value": "F"}, "delta": -1.0}]'::jsonb, 'Letter-grade location safety (A+ through F). Placeholder in v1: no pipeline stage emits it — the value arrives via human override until the dedicated safety module (DESIGN §18, P3-17) lands. Inherently low-confidence by design (DESIGN R8) — frame as such, never as fact.', 'web_search', 'reviews', 'decision_relevant', 'standard_ladder'),
  ('pool', 'Pool', 'amenities', 'rent', 'property', '{"type": "string", "enum": ["indoor", "outdoor", "indoor_and_outdoor", "unspecified", "none"]}'::jsonb, null, '[{"match": {"op": "eq", "value": "indoor_and_outdoor"}, "delta": 0.5}, {"match": {"op": "in", "value": ["indoor", "outdoor"]}, "delta": 0.25}, {"match": {"op": "eq", "value": "unspecified"}, "delta": 0.25}, {"match": {"op": "eq", "value": "none"}, "delta": 0.0}]'::jsonb, 'Shared Property pool facilities only: indoor, outdoor, both, unspecified type, or explicitly none. Do not infer private-unit pools.', null, 'listing_details', 'available_sources_only', 'verified_positive_preferred'),
  ('fitness_center', 'Fitness center or gym', 'amenities', 'rent', 'property', '{"type": "boolean"}'::jsonb, null, '[{"match": {"op": "bool", "value": true}, "delta": 0.25}, {"match": {"op": "bool", "value": false}, "delta": 0.0}]'::jsonb, 'True only for an on-site resident fitness center or gym.', null, 'listing_details', 'available_sources_only', 'verified_positive_preferred'),
  ('clubhouse', 'Clubhouse', 'amenities', 'rent', 'property', '{"type": "boolean"}'::jsonb, null, '[{"match": {"op": "bool", "value": true}, "delta": 0.25}, {"match": {"op": "bool", "value": false}, "delta": 0.0}]'::jsonb, 'True only when the Property advertises a resident clubhouse.', null, 'listing_details', 'available_sources_only', 'verified_positive_preferred'),
  ('emergency_maintenance', 'Emergency maintenance', 'management', 'rent', 'property', '{"type": "string", "enum": ["emergency_service", "24_hour_emergency", "none"]}'::jsonb, null, '[{"match": {"op": "eq", "value": "24_hour_emergency"}, "delta": 0.5}, {"match": {"op": "eq", "value": "emergency_service"}, "delta": 0.25}, {"match": {"op": "eq", "value": "none"}, "delta": 0.0}]'::jsonb, '24_hour_emergency only when 24-hour emergency maintenance is explicit; emergency_service for emergency maintenance without a 24-hour promise; none only when explicitly unavailable.', null, 'listing_details', 'available_sources_only', 'verified_positive_preferred'),
  ('maintenance_on_site', 'Maintenance on site', 'management', 'rent', 'property', '{"type": "boolean"}'::jsonb, null, '[{"match": {"op": "bool", "value": true}, "delta": 0.25}, {"match": {"op": "bool", "value": false}, "delta": 0.0}]'::jsonb, 'True only when on-site maintenance staff or service is advertised.', null, 'listing_details', 'available_sources_only', 'verified_positive_preferred'),
  ('management_on_site', 'Management on site', 'management', 'rent', 'property', '{"type": "boolean"}'::jsonb, null, '[{"match": {"op": "bool", "value": true}, "delta": 0.25}, {"match": {"op": "bool", "value": false}, "delta": 0.0}]'::jsonb, 'True only when on-site Property management is advertised.', null, 'listing_details', 'available_sources_only', 'verified_positive_preferred'),
  ('online_payments', 'Online payments', 'management', 'rent', 'property', '{"type": "boolean"}'::jsonb, null, '[{"match": {"op": "bool", "value": true}, "delta": 0.25}, {"match": {"op": "bool", "value": false}, "delta": 0.0}]'::jsonb, 'True only when online rent payments are explicit. A generic resident portal alone is display evidence and does not prove this capability.', null, 'listing_details', 'available_sources_only', 'verified_positive_preferred'),
  ('online_maintenance_requests', 'Online maintenance requests', 'management', 'rent', 'property', '{"type": "boolean"}'::jsonb, null, '[{"match": {"op": "bool", "value": true}, "delta": 0.25}, {"match": {"op": "bool", "value": false}, "delta": 0.0}]'::jsonb, 'True only when residents can submit maintenance requests online. A generic resident portal alone is display evidence and does not prove this capability.', null, 'listing_details', 'available_sources_only', 'verified_positive_preferred'),
  ('package_handling', 'Package handling', 'amenities', 'rent', 'property', '{"type": "string", "enum": ["locker", "secured_room", "office", "unsecured_area", "none"]}'::jsonb, null, '[{"match": {"op": "eq", "value": "locker"}, "delta": 0.5}, {"match": {"op": "eq", "value": "secured_room"}, "delta": 0.25}, {"match": {"op": "eq", "value": "office"}, "delta": 0.1}, {"match": {"op": "eq", "value": "unsecured_area"}, "delta": 0.0}, {"match": {"op": "eq", "value": "none"}, "delta": 0.0}]'::jsonb, 'How resident packages are handled: dedicated locker, secured room, office receipt, unsecured area, or explicitly none.', null, 'listing_details', 'available_sources_only', 'verified_positive_preferred'),
  ('smoking_policy', 'Smoking policy', 'tenancy', 'rent', 'property', '{"type": "string", "enum": ["smoke_free_property", "designated_areas_only", "permitted"]}'::jsonb, null, '[{"match": {"op": "eq", "value": "smoke_free_property"}, "delta": 0.0}, {"match": {"op": "eq", "value": "designated_areas_only"}, "delta": -0.25}, {"match": {"op": "eq", "value": "permitted"}, "delta": -1.5}]'::jsonb, 'Property-wide smoking policy: fully smoke-free, permitted only in designated areas, or generally permitted. Silence is unknown.', null, 'listing_details', 'decision_relevant', 'standard_ladder'),
  ('property_types', 'Property types', 'amenities', 'rent', 'property', '{"type": "array", "items": {"type": "string", "enum": ["apartment", "condo", "townhome", "duplex", "single_family", "loft", "other"]}, "minItems": 1, "uniqueItems": true}'::jsonb, null, '[{"match": {"op": "contains_any", "value": ["apartment", "condo", "townhome", "duplex", "single_family", "loft", "other"]}, "delta": 0.0}]'::jsonb, 'Every explicitly advertised Property type from the controlled vocabulary. Preserve multiple types; do not infer from architecture or a Floor Plan name.', null, 'listing_details', 'decision_relevant', 'standard_ladder'),
  ('unit_types', 'Unit types', 'unit', 'rent', 'floor_plan', '{"type": "array", "items": {"type": "string", "enum": ["apartment", "condo", "townhome", "duplex", "single_family", "loft", "other"]}, "minItems": 1, "uniqueItems": true}'::jsonb, null, '[{"match": {"op": "contains_any", "value": ["apartment", "condo", "townhome", "duplex", "single_family", "loft", "other"]}, "delta": 0.0}]'::jsonb, 'Every explicitly advertised type for the Floor Plan. Usually one value; preserve multiple types for a genuinely hybrid offering and do not infer from architecture.', null, 'listing_details', 'decision_relevant', 'standard_ladder'),
  ('internet_readiness', 'Internet readiness advertised', 'amenities', 'rent', 'property', '{"type": "boolean"}'::jsonb, null, '[{"match": {"op": "bool", "value": true}, "delta": 0.25}, {"match": {"op": "bool", "value": false}, "delta": 0.0}]'::jsonb, 'True only when the Source advertises general internet, high-speed internet, or fiber readiness for the Property. This does not verify provider serviceability, speed, Floor Plan coverage, or inclusion in rent; silence is unknown.', null, 'listing_details', 'available_sources_only', 'verified_positive_preferred')
